// Generate a candidate HTTP template string. We do not assume any specific
// grammar beyond what Parse() understands; failures are handled by bailing.
std::string tpl = FUZZ_PARAM_STR();

// Attempt to parse. If parsing fails (empty unique_ptr), bail to avoid
// returning an invalid object to the pool.
std::unique_ptr<google::grpc::transcoding::HttpTemplate> up =
    google::grpc::transcoding::HttpTemplate::Parse(tpl);
if (!up) { FUZZ_BAIL(); }

