FUZZ_SET_ATTR_INT(tmpl, "segments_size", static_cast<int>(segs.size()));
FUZZ_SET_ATTR_INT(tmpl, "variables_size", static_cast<int>(vars.size()));
FUZZ_SET_ATTR_INT(tmpl, "verb_len", static_cast<int>(v.size()));
// Note: we intentionally avoid mutating vars to preserve internal consistency.

