FUZZ_SET_ATTR_INT(tmpl, "segments_size", static_cast<int>(segs.size()));
// Record a checksum-ish value for potential later diagnostics.
FUZZ_SET_ATTR_INT(tmpl, "segments_total_len", static_cast<int>(total_len % 2048));

