FUZZ_SET_ATTR_INT(tmpl, "verb_len", static_cast<int>(verb.size()));
// Optionally record whether verb is empty or not as a boolean flag.
FUZZ_SET_ATTR_INT(tmpl, "has_verb", verb.empty() ? 0 : 1);

