import random
import string
from typing import List

# Generator for google/api/http.proto-style HTTP path templates
# Examples we try to cover:
# - Literal only: /v1/books
# - Variables: /v1/{name}
# - Variables with binding and wildcards: /v1/{name=projects/*}/topics
# - Double wildcard: /v1/{name=**}
# - Mix of literals and single-parameter wildcards: /a/*/b
# - Custom verb suffix: /v1/books:batchGet
# - Dotted field paths in variables: {book.name=shelves/*/books/*}
# - Negative end segments are internal; template syntax uses * / ** patterns.
# - Avoid malformed inputs; keep under 4096 bytes.

LITERALS = [
    "v1", "v2", "beta", "projects", "locations", "instances", "books",
    "shelves", "topics", "subscriptions", "users", "profiles", "photos",
    "media", "files", "datasets", "tables", "jobs", "operations",
]

CUSTOM_VERBS = [
    "get", "list", "create", "delete", "update", "patch", "batchGet",
    "search", "stream", "upload", "download"
]

FIELD_NAMES = [
    "name", "parent", "book", "shelf", "topic", "subscription",
    "project", "location", "instance", "user", "photo", "dataset",
    "table", "job", "operation"
]

# Path piece generators

def literal_seg(rng: random.Random) -> str:
    # Use URL-safe literal without slashes or forbidden strings
    base = rng.choice(LITERALS)
    # Occasionally append an ID-like suffix
    if rng.random() < 0.3:
        suffix = ''.join(rng.choices(string.ascii_lowercase + string.digits, k=rng.randint(1, 6)))
        return f"{base}-{suffix}"
    return base


def single_wildcard() -> str:
    return "*"


def double_wildcard() -> str:
    return "**"


def field_path(rng: random.Random) -> str:
    # Create dotted field path like book.name or project.location.instance
    parts = [rng.choice(FIELD_NAMES)]
    if rng.random() < 0.7:
        # 1-2 more components
        for _ in range(rng.randint(0, 2)):
            parts.append(rng.choice(FIELD_NAMES))
    return ".".join(parts)


def binding_pattern(rng: random.Random) -> str:
    # Right side of {field=pattern}; pattern is a path pattern composed of literals and wildcards
    segs: List[str] = []
    n = rng.randint(1, 4)
    for i in range(n):
        r = rng.random()
        if r < 0.55:
            segs.append(literal_seg(rng))
        elif r < 0.85:
            segs.append(single_wildcard())
        else:
            # Put ** only at end to keep validity high
            segs.append(double_wildcard() if i == n - 1 else single_wildcard())
    # Avoid producing consecutive ** or internal ** by normalizing
    cleaned: List[str] = []
    for i, s in enumerate(segs):
        if s == "**" and i != len(segs) - 1:
            cleaned.append("*")
        else:
            cleaned.append(s)
    return "/".join(cleaned)


def variable_seg(rng: random.Random) -> str:
    # Either simple {name} or binding {name=pattern}
    if rng.random() < 0.4:
        return "{" + rng.choice(FIELD_NAMES) + "}"
    else:
        fp = field_path(rng)
        pat = binding_pattern(rng)
        return "{" + fp + "=" + pat + "}"


def mixed_segment(rng: random.Random) -> str:
    r = rng.random()
    if r < 0.5:
        return literal_seg(rng)
    elif r < 0.7:
        return variable_seg(rng)
    elif r < 0.9:
        return single_wildcard()
    else:
        # Double wildcard is best at end; the caller may place at end.
        return double_wildcard()


def maybe_custom_verb(rng: random.Random) -> str:
    if rng.random() < 0.5:
        return ":" + rng.choice(CUSTOM_VERBS)
    return ""


def build_template(rng: random.Random) -> str:
    # Construct a path with 1-8 segments
    n = rng.randint(1, 8)
    segs: List[str] = []
    for i in range(n):
        s = mixed_segment(rng)
        # Keep ** only at final position to maximize parse success
        if s == "**" and i != n - 1:
            s = "*"
        segs.append(s)
    # Avoid empty or forbidden segments; ensure first segment is literal-like often
    if segs and segs[0] in ("*", "**") and rng.random() < 0.8:
        segs[0] = literal_seg(rng)
    # Ensure we don't produce "/." or "/.." literals
    segs = ["." if s == "/." else (".." if s == "/.." else s) for s in segs]
    path = "/" + "/".join(segs)

    # Occasionally append custom verb
    if rng.random() < 0.35:
        path += maybe_custom_verb(rng)
    return path


def generate(seed: int) -> bytes:
    rng = random.Random(seed)
    # Choose a strategy
    strategy = rng.random()

    if strategy < 0.15:
        # Simple literal path
        count = rng.randint(1, 5)
        segs = [literal_seg(rng) for _ in range(count)]
        s = "/" + "/".join(segs)
    elif strategy < 0.30:
        # Single variable
        s = "/v1/" + variable_seg(rng)
    elif strategy < 0.45:
        # Variable with binding and additional literals
        s = "/v1/" + variable_seg(rng) + "/" + literal_seg(rng)
        if rng.random() < 0.5:
            s += "/" + literal_seg(rng)
        if rng.random() < 0.3:
            s += maybe_custom_verb(rng)
    elif strategy < 0.60:
        # Double wildcard at end via binding
        fp = field_path(rng)
        s = f"/v1/{{{fp}=**}}/" + literal_seg(rng)
        if rng.random() < 0.4:
            s += "/" + literal_seg(rng)
    elif strategy < 0.75:
        # Mix of literals and single wildcards
        parts = []
        for _ in range(rng.randint(2, 6)):
            parts.append(rng.choice([literal_seg(rng), single_wildcard()]))
        s = "/" + "/".join(parts)
        if rng.random() < 0.4:
            s += maybe_custom_verb(rng)
    else:
        # General builder with diverse segments
        s = build_template(rng)

    # Trim to size limit
    bs = s.encode('utf-8')[:4096]
    return bs
